def describe_next_generation_intelligence_architecture() -> str:
    lines = [
        "TitanAI Next Generation Intelligence Architecture Era",
        "",
        "This era focuses on the core intelligence architecture of TitanAI: more accurate, reliable, explainable, and capable of handling complex projects while working effectively alongside humans.",
        "",
    ]
    for capability in NEXT_GENERATION_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
